  1920 // ---------------------------------------------------------------------------
  1921 // Need-list enforcement for the data-plane receive
  1922 // ---------------------------------------------------------------------------
  1923 
  1924 /// Sink decorator that enforces the session's need-list contract on the
  1925 /// data-plane receive, giving it the SAME strictness the in-stream
  1926 /// carrier applies inline in the control loop (`outstanding.remove`).
  1927 /// `execute_receive_pipeline` writes socket-provided paths directly, so
  1928 /// without this a peer could substitute an off-need-list path for a
  1929 /// needed one (count-preserving), duplicate one, or send resume block
  1930 /// records the session never negotiated (review otp-4b-1 F1). Every
  1931 /// written path must be a granted, not-yet-received need. Resume
  1932 /// sessions (otp-7b) additionally validate + claim block records
  1933 /// against the shared [`ResumeHeaders`] grant map — with the identical
  1934 /// strictness the in-stream `claim_resume_record` applies — and count
  1935 /// completions into the shared resumed counter; in a non-resume session
  1936 /// block records are rejected outright. The shared [`OutstandingNeeds`]
  1937 /// set makes completion `is_empty()` for both carriers.
  1938 pub(super) struct NeedListSink {
  1939     inner: Arc<dyn TransferSink>,
  1940     outstanding: OutstandingNeeds,
  1941     granted_headers: GrantedHeaders,
  1942     small_file_probe: Option<BoundSmallFileProbe>,
  1943     /// `Some` iff the session negotiated resume (otp-7b): the shared
  1944     /// grant map + resumed counter block records are validated and
  1945     /// claimed against. `None` ⇒ any block record is a violation.
  1946     resume: Option<ResumeRecv>,
  1947 }
  1948 
  1949 impl NeedListSink {
  1950     pub(super) fn new(
  1951         inner: Arc<dyn TransferSink>,
  1952         outstanding: OutstandingNeeds,
  1953         granted_headers: GrantedHeaders,
  1954         resume: Option<ResumeRecv>,
  1955         small_file_probe: Option<BoundSmallFileProbe>,
  1956     ) -> Self {
  1957         Self {
  1958             inner,
  1959             outstanding,
  1960             granted_headers,
  1961             resume,
  1962             small_file_probe,
  1963         }
  1964     }
