  2069     /// Remove `path` from the outstanding set, or fault: a path that is
  2070     /// not present is either off the need list or a duplicate delivery.
  2071     fn claim(&self, path: &str) -> Result<()> {
  2072         let removed = if let Some(probe) = &self.small_file_probe {
  2073             let wait_started = probe.start();
  2074             let mut outstanding = self
  2075                 .outstanding
  2076                 .lock()
  2077                 .expect("outstanding-needs lock poisoned");
  2078             let wait = wait_started.elapsed();
  2079             let hold_started = probe.start();
  2080             let removed = outstanding.remove(path);
  2081             drop(outstanding);
  2082             let hold = hold_started.elapsed();
  2083             probe.note_claim(
  2084                 SmallFileCarrier::Tcp,
  2085                 1,
  2086                 1,
  2087                 usize::from(removed),
  2088                 wait,
  2089                 hold,
  2090             );
  2091             removed
  2092         } else {
  2093             self.outstanding
  2094                 .lock()
  2095                 .expect("outstanding-needs lock poisoned")
  2096                 .remove(path)
  2097         };
  2098         if removed {
  2099             Ok(())
  2100         } else {
  2101             Err(eyre::Report::new(
  2102                 SessionFault::protocol_violation(format!(
  2103                     "data-plane payload for '{path}' which is not an outstanding need \
  2104                  (off the need list, or a duplicate delivery)"
  2105                 ))
  2106                 .with_path(path),
  2107             ))
  2108         }
  2109     }
