   194     /// otp-6: the unified session's single mirror-delete rule. Given the
   195     /// COMPLETE set of source-side relative file paths (posix, exactly as
   196     /// they arrived on the wire) and the enumeration `filter`, enumerate
   197     /// `dest_root` and return the extraneous entries — dest paths absent
   198     /// from the source set — dirs deepest-first.
   199     ///
   200     /// The session manifest lists files only (directories are implicit, see
   201     /// `spawn_manifest_task`), so a directory's survival is derived here from
   202     /// the parent chains of the kept files: a dir is extraneous iff no kept
   203     /// source file lives under it. This is the same derivation the daemon's
   204     /// `plan_extraneous_entries` does; centralizing it here is the session's
   205     /// "one delete rule" that replaces the three per-direction purges at
   206     /// cutover.
   207     ///
   208     /// `filter` scopes the dest enumeration: for `MirrorMode::FilteredSubset`
   209     /// it is the user's filter (so out-of-scope dest entries are never
   210     /// candidates); for `MirrorMode::All` it is `FileFilter::default()` (the
   211     /// whole dest tree is in scope).
   212     pub fn plan_session_deletions(
   213         &self,
   214         dest_root: &Path,
   215         source_files: &HashSet<String>,
   216         filter: &FileFilter,
   217     ) -> Result<MirrorDeletionPlan> {
   218         let enumerator = FileEnumerator::new(filter.clone_without_cache());
   219         let dest_entries = enumerator.enumerate_local(dest_root)?;
   220 
   221         // Kept set = every source file plus each of its ancestor dirs, so a
   222         // directory holding a kept file is itself kept (never deleted).
   223         let mut source_set: HashSet<CasefoldKey> = HashSet::new();
