   225             let path = Path::new(rel);
   226             source_set.insert(CasefoldKey::new(path));
   227             let mut current = path.parent();
   228             while let Some(parent) = current {
   229                 if parent.as_os_str().is_empty() {
   230                     break;
   231                 }
   232                 source_set.insert(CasefoldKey::new(parent));
   233                 current = parent.parent();
   234             }
   235         }
