   237         let dest_set = dest_entries
   238             .into_iter()
   239             .map(|e| (e.relative_path, matches!(e.kind, EntryKind::Directory)))
   240             .collect::<Vec<_>>();
   241 
   242         Ok(plan_from_sets(dest_root, source_set, dest_set))
   243     }
