   330 fn plan_from_sets(
   331     dest_root: &Path,
   332     source_set: HashSet<CasefoldKey>,
   333     dest_entries: Vec<(PathBuf, bool)>,
   334 ) -> MirrorDeletionPlan {
   335     let mut files = Vec::new();
   336     let mut dirs = Vec::new();
   337 
   338     for (rel, is_dir) in dest_entries {
   339         if rel.as_os_str().is_empty() {
   340             continue;
   341         }
   342         if source_set.contains(&CasefoldKey::new(&rel)) {
   343             continue;
   344         }
